#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_SIZE 10000
#define OPERATOR_NUM_LEN 100
#define OPERATOR_NUM_SIZE 1000

char s[MAX_SIZE] = {'\0'};

long calcExpStr(const char *exp) {
    // 记录表达式中各块的操作数
    long stack[OPERATOR_NUM_SIZE];
    int stack_size = 0;

    // 各块操作数的"值"部分的缓存容器
    char numStr[OPERATOR_NUM_LEN] = {'\0'};
    int numStr_size = 0;

    // 各块操作数的"系数"部分，默认为1
    long num_coef = 1;

    int i = 0;
    while (exp[i] != '\0') {
        char c = exp[i];

        if (c >= '0' && c <= '9') {
            numStr[numStr_size++] = c;
        } else {
            // 如果扫描到的字符c是运算符，那么该运算符打断了前面操作数的扫描，前面操作数 = 系数 * 值
            long num = num_coef * atol(numStr);
            stack[stack_size++] = num;

            // 清空缓存容器，用于下一个操作数的”值“记录
            numStr_size = 0;
            memset(numStr, '\0', OPERATOR_NUM_LEN);

            if (c == '+') {
                // 如果运算符是加法，则后一个操作数的系数为1
                num_coef = 1;
            } else if (c == '-') {
                // 如果运算符是减法，则后一个操作数的系数为-1
                num_coef = -1;
            } else if (c == '*') {
                // 如果运算符是乘法，则后一个操作数的系数为栈顶值，比如2*3，其中2可以当作3的系数
                num_coef = stack[--stack_size];
            }
        }

        i++;
    }

    // 收尾处理
    if (numStr_size > 0) {
        long num = num_coef * atol(numStr);
        stack[stack_size++] = num;
    }

    // 表达式分块后，每一块独立计算，所有块的和就是表达式的结果
    long res = 0;
    for (int j = 0; j < stack_size; j++) {
        res += stack[j];
    }

    return res;
}

int isDigit(char c) {
    return c >= '0' && c <= '9';
}

int isOperator(char c) {
    return c == '+' || c == '-' || c == '*';
}

int main() {
    gets(s);

    // 记录最长合法表达式的长度
    int maxLen = 0;
    // 记录最长合法表达式的起始位置
    int start = -1;

    // 双指针找最长合法表达式
    int l = 0;
    int r = 0;

    while (s[r] != '\0') {
        // 合法表达式必须以数字开头
        while (s[l] != '\0' && !isDigit(s[l])) {
            l++;
        }

        if (s[l] == '\0') {
            break;
        }

        // l找到合法表达式的开头后，r指针扫开始描合法表达式剩余部门
        r = l + 1;

        while (s[r] != '\0') {
            // 如果r指针扫描到的是数字字符，则继续扫描
            // 如果r指针扫描到的是+-*符号，则需要看r-1字符是不是+-*符号，如果不是则继续扫描
            if (isDigit(s[r]) || (isOperator(s[r]) && !isOperator(s[r - 1]))) {
                r++;
            } else {
                // 其他情况中断r扫描
                break;
            }
        }

        // 此时 [l, r) 左闭右开范围就是合法表达式
        int len = r - l;

        // 注意如果r-1位置是+-*符号，则不能包含
        if (isOperator(s[r - 1])) {
            len -= 1;
        }

        // 记录最长的合法表达式长度，以及起始位置
        if (len > maxLen) {
            maxLen = len;
            start = l;
        }

        // 找到一个合法表达式后，继续找下一个合法表达式
        l = r + 1;
    }

    if (start == -1) {
        // 如果没找到合法表达式，则直接打印0
        puts("0");
    } else {
        // 找到最长合法表达式，则计算其结果打印
        s[start + maxLen] = '\0';
        printf("%ld\n", calcExpStr(s + start));
    }

    return 0;
}
